/**
 * Keeps the baseline x-axis categories when filtered SQL drops rows, zero-filling
 * series values for missing categories so bars/lines animate in place instead of
 * collapsing the axis.
 */
export function alignChartDataToBaselineX(
	baseline: Record<string, unknown>[],
	filtered: Record<string, unknown>[],
	xAxisKey: string,
	seriesKeys: string[],
): Record<string, unknown>[] {
	if (baseline.length === 0) {
		return filtered;
	}

	const baselineXKey = resolveDataKey(baseline, xAxisKey);
	const filteredXKey = resolveDataKey(filtered, xAxisKey);
	const resolvedSeriesKeys = seriesKeys.map((key) => resolveDataKey(baseline, key));

	const filteredByX = new Map<string, Record<string, unknown>>();
	for (const row of filtered) {
		filteredByX.set(String(row[filteredXKey] ?? row[baselineXKey]), row);
	}

	return baseline.map((baseRow) => {
		const xValue = String(baseRow[baselineXKey]);
		const match = filteredByX.get(xValue);
		if (!match) {
			const emptyRow = { ...baseRow };
			for (const key of resolvedSeriesKeys) {
				emptyRow[key] = 0;
			}
			return emptyRow;
		}

		const next = { ...baseRow };
		for (const key of resolvedSeriesKeys) {
			const matchKey = resolveDataKey([match], key);
			const value = match[matchKey] ?? match[key];
			next[key] = typeof value === 'number' || value === null ? value : value === undefined ? 0 : value;
		}
		return next;
	});
}

/** Counts the successfully rendered `display_chart` tool calls across a conversation. */

import { alignChartDataToBaselineX, resolveDataKey, resolvePieTooltipLabel } from './charts.utils';

describe('resolveDataKey', () => {
	it('returns an empty string when the key is undefined (kpi cards have no x-axis)', () => {
		expect(resolveDataKey([{ revenue: 100 }], undefined)).toBe('');
	});
});

describe('resolvePieTooltipLabel', () => {
	it('returns the slice category name from the payload', () => {
		expect(resolvePieTooltipLabel([{ name: 'US' }])).toBe('US');
	});

	it('uses only the first (hovered) slice', () => {
		expect(resolvePieTooltipLabel([{ name: 'FR' }, { name: 'DE' }])).toBe('FR');
	});

	it('coerces non-string names to a string', () => {
		expect(resolvePieTooltipLabel([{ name: 2024 }])).toBe('2024');
	});

	it('returns an empty string instead of "undefined" when the name is missing', () => {
		expect(resolvePieTooltipLabel([{}])).toBe('');
	});

	it('returns an empty string for an empty or missing payload', () => {
		expect(resolvePieTooltipLabel([])).toBe('');
		expect(resolvePieTooltipLabel(undefined)).toBe('');
	});
});

describe('alignChartDataToBaselineX', () => {
	it('keeps baseline x categories and zero-fills missing filtered rows', () => {
		const baseline = [
			{ month: 'Jan', revenue: 10 },
			{ month: 'Feb', revenue: 20 },
			{ month: 'Mar', revenue: 30 },
		];
		const filtered = [{ month: 'Feb', revenue: 8 }];

		expect(alignChartDataToBaselineX(baseline, filtered, 'month', ['revenue'])).toEqual([
			{ month: 'Jan', revenue: 0 },
			{ month: 'Feb', revenue: 8 },
			{ month: 'Mar', revenue: 0 },
		]);
	});
});

